"""Write asset briefs and a reproducible manifest. Provider calls use the bundled CLI directly."""
from pathlib import Path
import json
HERE=Path(__file__).resolve().parent
BASE='''Use case: style-transfer. Asset type: painted cardboard toy-theatre production asset.
Input image 1 is the approved visual identity reference. Preserve its exact cast, faces, costumes, muted gouache and ink, worn paper texture, brass pin joints and tragic French travelling theatre mood. This is flat hand-painted cardboard artwork, front-facing orthographic, not a photograph or a 3D render. Soft neutral illumination painted into the surface, no cast shadow on the background. No text, labels, numbers, watermark, logo, scenery, ground, strings or rods unless expressly requested. Genuine transparent alpha background, not a white or checkerboard drawing. Keep every separate item completely apart with broad clear gutters. No cropped paint at edges.\n'''
JOBS={}
def add(n,p,size='1024x1024',parts=False,bg='transparent'):
 (HERE/'prompts'/f'{n}.prompt').write_text(BASE+p,encoding='utf-8')
 JOBS[n]={'model':'gpt-image-2.6-sunburst','mode':'edit','reference':'src/key-art.png','size':size,'quality':'high','background':bg,'parts':parts,'raw_output':f'src/{n}.png'}
def main():
 for who,desc in [('dancer','the female dancer with chestnut bun, thoughtful sorrowful face, faded deep petrol-blue short scalloped ballet dress, cream stockings and ballet slippers'),('clown','the male backstage clown with dark wavy hair, gentle long face, tiny faded red clown nose, ivory shirt, patched slate waistcoat and charcoal trousers')]:
  add(f'{who}-core',f'''Extract and repaint {desc}. A TWO PART assembly sheet, exactly two fully disconnected islands. LEFT: her/his front-facing HEAD ONLY, including a tiny ordinary neck base, no shoulders, no strings, no huge smile, face subtly turned towards viewer's right; head about 330 pixels tall. RIGHT: front-facing TORSO ONLY, shoulder width 350 pixels, about 500 pixels high, from collar through waist and hips; NO head, NO arms, NO legs. Dancer torso includes short scalloped skirt, red sash knot at right waist but NO long hanging sash. Clown torso includes the short waistcoat and pelvis trouser top. Both shoulder sockets are plain round painted caps. Lower edge at upper thighs. Collar should cover the short neck when assembled; never a long neck. Two isolated flat cut pieces, no limbs, not a full figure. Even natural facial proportions, sad dignity.''',parts=True)
  add(f'{who}-arms',f'''A FOUR PART detachable arm sheet for {desc}. Exactly FOUR disconnected straight arm segments, arranged as a 2 by 2 grid. TOP LEFT: left upper arm from a round shoulder cap to round elbow cap. TOP RIGHT: right upper arm from round shoulder cap to round elbow cap. Both upper arms point straight DOWN, about 330 pixels long, with brass elbow pin. BOTTOM LEFT: left forearm from round elbow cap down to a complete expressive open hand, fingers loosely curled ready to grasp. BOTTOM RIGHT: right forearm from round elbow cap down to a complete expressive open hand. Both forearms point straight DOWN, each 360 pixels long including the hand. Female skin arms with tiny blue shoulder puff, male rolled ivory sleeves. Round joint overlaps; no arm bends painted in. No head, torso, legs, duplicate arms or props. Every piece separated by at least 60 pixels of real transparency, big generous segments, no guide lines.''',parts=True)
  add(f'{who}-legs',f'''A FOUR PART detachable leg sheet for {desc}. Exactly FOUR fully disconnected vertical leg segments arranged as a 2 by 2 grid. TOP LEFT: left THIGH from round hip cap to brass-pin knee cap, pointing straight down. TOP RIGHT: right THIGH from round hip cap to knee cap, straight down. BOTTOM LEFT: left SHIN from round knee cap down to ankle and complete shoe, foot pointing a little left. BOTTOM RIGHT: right SHIN from round knee cap down to ankle and complete shoe, foot pointing a little right. Thighs 320 pixels high, shins WITH shoes 390 pixels high. Dancer has cream stockings and worn ivory ballet slippers; clown has loose charcoal trouser legs and brown soft work shoes. Knee has round overlap so it bends physically. No torso, head, whole body, arms, labels or scenery. At least 60 pixels transparency between pieces.''',parts=True)
 add('canopy','Only the old theatre canvas roof border: a narrow long horizontal scalloped drape in faded oxblood and dusty ivory stripes, fraying golden fringe and stitched patches. Paint hangs from a mostly straight upper edge with shallow sag, torn trailing fabric at sides. ONE connected cutout across frame width, height less than one third width, NO upright posts, no backdrop, no stage, no people. This flies above the dancers.','1536x1024')
 add('cloud-wing','One narrow tall travelling-theatre scenery flat, painted storm-cloud scrolls and bare crooked branches, dusty slate blue and worn ochre edging. A visibly scuffed wooden vertical frame at one side, little wooden truck wheels at bottom. Cut silhouette follows clouds at inner edge. One connected piece, taller than wide. No people, no arch, no other object.','1024x1536')
 add('platform','One low wide wooden theatre platform viewed absolutely straight from audience: top surface a narrow strip of worn horizontal planks, face has dark vertical boards and scuffed ochre edges. Height one fifth width. Slight paper perspective on top but front view, no cast shadow, no stage around it, no curtains, no people. ONE isolated connected low rectangular riser. It will be reused in separate moving sections.','1536x1024')
 add('support','One long straight wooden theatre roof-support beam, VERTICAL, brass bolt at each end, scuffed ochre paint, cracked dark wood. One connected piece, about ten times taller than wide, upright isolated, no attached crossbar, NO other props, no ropes, no background.','1024x1536')
 add('ladder','One old narrow wooden backstage ladder viewed absolutely front-on, with SIX rungs between two uprights, scuffed dark ochre wood. Real transparent holes between rungs; one connected isolated object, no floor, no person.','1024x1536')
 add('stool','A simple battered wooden theatre stool from the reference, round oval top, four short legs and connecting braces, audience front view. One isolated connected object. No hat or other object on it.','1024x1024')
 add('broom','One long old straw broom, straight vertical wooden handle, compact broad bundle of straw at bottom, tied with frayed cord, reference paint style. Complete handle tip and all bristles visible, one isolated connected object.','1024x1536')
 add('hat','Only the clown\'s battered charcoal bowler hat with faded oxblood band, turned slightly up to show crown and oval brim. ONE isolated connected hat, no head, no stool, no flowers.','1024x1024')
 add('trunk','One scuffed old rectangular travelling theatre packing trunk, CLOSED, vintage blackened brown wood, tarnished ochre brass corner pieces and two leather straps, a broad central handle. Straight front view with a little lid top visible. No text or stickers or other objects. One isolated connected object.','1536x1024')
 add('ribbon-fold','A neatly folded length of faded crimson costume sash, loose flat bundle on its side with two ribbon tails. Folded fabric only, no hands, no body, no floor. Same worn red fabric as dancer\'s sash, one isolated connected cutout.','1024x1024')
 add('poster','''Create a portrait vintage gouache theatre poster IMAGE with no text. Same two living adult marionettes, exact faces and costumes. They bow beside one another on the few remaining boards, elbows and knees bent, hands joined, expressions sorrowful and exhausted. Broken canvas roof and crooked cloud scenery recede behind them; packing trunk and broom wait at their feet. Tragedy, quiet resolve, no triumphant pose, no happy ending, no spectators or confetti. Sash droops from their hands. Cardboard paint and brass joints. Keep top 18 percent and bottom 16 percent plain dark navy paper for titles to be printed later. Opaque full composition with navy edges, NO text, NO watermark.''','1024x1536',bg='opaque')
 (HERE/'prompts/jobs.json').write_text(json.dumps(JOBS,indent=2)+'\n',encoding='utf-8')
 print(f'{len(JOBS)} explicit Sunburst asset briefs written')
if __name__=='__main__':main()
